25	// Registry 是舱单与配载的本地登记处。
26	//
27	// Registry 的所有方法都可以安全地并发调用。
28	type Registry struct {
29		mu           sync.Mutex
30		compartments map[string]*compartment
31		cargos       map[string]*cargo
32		adjustments  map[string]*AdjustmentResult // 已成功调整的编号 -> 保存的结果快照
33		contents     map[string]string            // 已成功调整的编号 -> 规范化内容键
34	}
35	
36	// NewRegistry 创建一个空的登记处。
37	func NewRegistry() *Registry {
38		return &Registry{
39			compartments: make(map[string]*compartment),
40			cargos:       make(map[string]*cargo),
41			adjustments:  make(map[string]*AdjustmentResult),
42			contents:     make(map[string]string),
43		}
44	}
