46	// RegisterCompartment 登记一个舱位。
47	// 编号去掉首尾空白后不得为空，maxWeight 必须为正整数（千克）。
48	// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
49	func (r *Registry) RegisterCompartment(id string, maxWeight int64) error {
50		r.mu.Lock()
51		defer r.mu.Unlock()
52	
53		cid := strings.TrimSpace(id)
54		if cid == "" {
55			return fail(ErrInvalidID, "", "舱位编号为空")
56		}
57		if maxWeight <= 0 {
58			return fail(ErrInvalidWeight, cid, "舱位 %s 最大承重必须为正整数千克，当前为 %d", cid, maxWeight)
59		}
60		if _, exists := r.compartments[cid]; exists {
61			return fail(ErrAlreadyExists, cid, "舱位 %s 已存在", cid)
62		}
63		r.compartments[cid] = &compartment{
64			id:        cid,
