75	func (r *Registry) RegisterCargo(id string, weight int64, destination string, allowMixed bool) error {
76		r.mu.Lock()
77		defer r.mu.Unlock()
78	
79		cid := strings.TrimSpace(id)
80		if cid == "" {
81			return fail(ErrInvalidID, "", "货物编号为空")
82		}
83		if weight <= 0 {
84			return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
85		}
