		if c.ID == id {
			return c
		}
	}
	t.Fatalf("货物 %s 不在清单 %+v", id, v)
	return CargoView{}
}

// 场景1：未装载货物装入 C1，After 中应 Loaded=true、CompartmentID=C1。
func TestVerifyLoadAfterState(t *testing.T) {
	r := NewRegistry()
	r.RegisterCompartment("C1", 100)
	r.RegisterCargo("G1", 30, "X", false)
	res, err := r.Preview([]Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})
	if err != nil {
		t.Fatal(err)
	}
	cv := findCargo(t, res.Compartments[0].After, "G1")
	if !cv.Loaded || cv.CompartmentID != "C1" || cv.Weight != 30 || cv.Destination != "X" || cv.AllowMixed {
		t.Fatalf("After 中 G1 状态错误: %+v", cv)
	}
}

// 场景2：C1->C2 移动，C1 Before 保留原位置，C2 After 显示已装载且属 C2。
func TestVerifyMoveAfterState(t *testing.T) {
	r := NewRegistry()
	r.RegisterCompartment("C1", 100)
	r.RegisterCompartment("C2", 100)
	r.RegisterCargo("G1", 30, "X", true)
	mustAdjust(t, r, "A1", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})
	res, err := r.Preview([]Op{{Kind: OpMove, CargoID: "G1", Target: "C2"}})
	if err != nil {
		t.Fatal(err)
	}
	before := findCargo(t, res.Compartments[0].Before, "G1")
	if !before.Loaded || before.CompartmentID != "C1" {
		t.Fatalf("Before 应保留原位置: %+v", before)
	}
	after := findCargo(t, res.Compartments[1].After, "G1")
	if !after.Loaded || after.CompartmentID != "C2" {
		t.Fatalf("After 应显示新舱位: %+v", after)
	}
}

// 场景3：交换后各货物显示交换后的舱位。
func TestVerifySwapAfterState(t *testing.T) {
	r := NewRegistry()
	r.RegisterCompartment("C1", 30)
	r.RegisterCompartment("C2", 30)
	r.RegisterCargo("G1", 30, "X", false)
	r.RegisterCargo("G2", 30, "X", false)
	mustAdjust(t, r, "A1", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: OpLoad, CargoID: "G2", Target: "C2"},
	})
	res, err := r.Preview([]Op{
		{Kind: OpMove, CargoID: "G1", Target: "C2"},
		{Kind: OpMove, CargoID: "G2", Target: "C1"},
	})
	if err != nil {
		t.Fatal(err)
	}
	if c := findCargo(t, res.Compartments[0].After, "G2"); c.CompartmentID != "C1" || !c.Loaded {
		t.Fatalf("C1 After 中 G2 错误: %+v", c)
	}
	if c := findCargo(t, res.Compartments[1].After, "G1"); c.CompartmentID != "C2" || !c.Loaded {
		t.Fatalf("C2 After 中 G1 错误: %+v", c)
	}
}

// 场景4：被拒绝的预览，After 仍显示预计位置。
func TestVerifyRejectedAfterState(t *testing.T) {
	r := NewRegistry()
	r.RegisterCompartment("C1", 50)
	r.RegisterCargo("G1", 60, "X", true)
	res, err := r.Preview([]Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})
	if err != nil {
		t.Fatal(err)
	}
	if res.Submittable {
		t.Fatal("应不可提交")
	}
	c := findCargo(t, res.Compartments[0].After, "G1")
	if !c.Loaded || c.CompartmentID != "C1" {
		t.Fatalf("被拒绝安排的 After 也应显示预计位置: %+v", c)
	}
}

// 场景5：提交成功后实际状态与 After 一致（含 Loaded/CompartmentID）。
func TestVerifyCommitMatchesAfter(t *testing.T) {
	r := NewRegistry()
	r.RegisterCompartment("C1", 100)
	r.RegisterCargo("G1", 30, "X", false)
	ops := []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}}
	res, err := r.Preview(ops)
	if err != nil {
		t.Fatal(err)
	}
	mustAdjust(t, r, "A1", ops)
	got, _ := r.Compartment("C1")
	want := res.Compartments[0].After
	if len(got.Cargo) != len(want.Cargo) {
		t.Fatal("清单长度不一致")
	}
	for i := range got.Cargo {
		if got.Cargo[i] != want.Cargo[i] {
			t.Fatalf("提交后货物状态与 After 不一致: got=%+v want=%+v", got.Cargo[i], want.Cargo[i])
		}
	}
}
